function canSwim(isSick, hasPass, hasWristband) {
  return !isSick && (hasPass || hasWristband);
}

function canBorrow(hasCard, isOverdue, isStaff) {
  return !isOverdue && (hasCard || isStaff);
}

function canPlay(isRaining, hasBall, hasFriends) {
  return !isRaining && (hasBall || hasFriends);
}

function canEnterRide(isTall, hasTicket, isGuest) {
  return hasTicket && (isTall || isGuest);
}

function isRefused(isSick, hasPass, hasWristband) {
  return isSick || (!hasPass && !hasWristband);
}

function needsReview(isDraft, isApproved, isUrgent) {
  return isDraft || (!isApproved && isUrgent);
}
